package main
import("testing";"os";"encoding/json";"context";"github.com/jackc/pgx/v5";"strings")
func bulkFixture(t *testing.T)map[string]json.RawMessage{t.Helper();raw,e:=os.ReadFile("/Users/freelancer/Documents/PhotoEditor/work/rtx-user-three-media-dispatch-r2/actual-bulk-result-probe.json");if e!=nil{t.Fatal(e)};var p struct{After []map[string]json.RawMessage};if json.Unmarshal(raw,&p)!=nil{t.Fatal("fixture")};for _,r:=range p.After{if len(r["result"])>5{return r}};t.Fatal("actual full projection missing");return nil}
func TestActualRollbackProjectionShape(t *testing.T){r:=bulkFixture(t);own,full,e:=checkBulkRow(r);if e!=nil||!own||!full{t.Fatal(own,full,e)};before:=row(map[string]string{"id":"foreign","result":"foreign"});if own,_,e=checkBulkRow(before);own||e!=nil{t.Fatal("foreign allowed")}}
func TestBulkImmutableBindingsRefused(t *testing.T){for _,k:=range []string{"tenant_id","bulk_operation_id","snapshot_ordinal","status","error_code"}{r:=bulkFixture(t);r[k]=json.RawMessage(`"wrong"`);if _,_,e:=checkBulkRow(r);e==nil{t.Fatal(k)}}}
func TestBulkExtraResultOrWrongRefsRefused(t *testing.T){for _,mode:=range []string{"extra","event","variant","reference","missing"}{r:=bulkFixture(t);var result map[string]any;json.Unmarshal(r["result"],&result);switch mode{case "extra":result["secret"]="not permitted";case "event":result["media_retry_event_id"]="00000000-0000-0000-0000-000000000000";default:a:=result["derivatives"].([]any);if mode=="missing"{result["derivatives"]=a[:3]}else{ref:=a[0].(map[string]any);if mode=="variant"{ref["variant"]="unreviewed"}else{ref["artifact_id"]="not uuid"}}};r["result"],_=json.Marshal(result);if _,_,e:=checkBulkRow(r);e==nil{t.Fatal(mode)}}}
func TestOnlyResultCellProjected(t *testing.T){r:=bulkFixture(t);r["other_immutable_column"]=json.RawMessage(`"retained"`);s:=fixture(t);skip,e:=s.normalize("bulk_item_results",r);if skip||e!=nil||r["result"]!=nil||string(r["other_immutable_column"])!=`"retained"`||r["created_at"]==nil{t.Fatal("row improperly skipped or columns erased",e)}}
type canonicalTx struct{pgx.Tx;accepted bool;query string}
func(t *canonicalTx)QueryRow(_ context.Context,q string,_ ...any)pgx.Row{t.query=q;return controlRow(func(d ...any)error{*d[0].(*bool)=t.accepted;return nil})}
func TestCanonicalMembershipRefusalAndSQLBinding(t *testing.T){for _,accepted:=range []bool{false,true}{tx:=&canonicalTx{accepted:accepted};e:=validateBulkRow(context.Background(),tx,bulkFixture(t));if accepted!=(e==nil){t.Fatal("canonical gate",e)};for _,needle:=range []string{"si.item_id=j.item_id","si.asset_version_id=j.asset_version_id","j.status='completed'","t.canonical_result_id","a.produced_fence=q.fencing_token","m.output_role='derivative_manifest'","jsonb_array_length(q.outputs)=2"}{if !strings.Contains(tx.query,needle){t.Fatal(needle)}}}}
func TestOutsideDiagnosticOnlyStaticCodeAndTables(t *testing.T){e:=protectedDiff(snapshot{"bulk_item_results":"a"},snapshot{"bulk_item_results":"b"});d:=diagnostic(e);if d["guard_code"]!="OUTSIDE_PROTECTED_DIFF"||d["tables"]!="bulk_item_results"||strings.Contains(d["tables"],"a,b"){t.Fatal(d)}}
